import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('onError rejection values', () => {
  // specs/hal-engine-config-hooks/spec.md#8
  it('preserves rejection values as causes while rethrowing them', async () => {
    const existingError = new Error('existing');
    for (const reason of ['string boom', {code: 503}, undefined, existingError]) {
      const provider: AIProvider = {
        // eslint-disable-next-line require-yield
        async *sendMessage(): AsyncGenerator<MessageChunk> {
          throw reason;
        },
        async generateStructured<T>(): Promise<T> {
          return {} as T;
        },
      };
      const session: ChatSession = {
        sessionId: 'test',
        userId: 'user',
        entries: [{role: 'user', content: 'hello', timestamp: new Date().toISOString()}],
      };
      const onError = jest.fn(async (_session: ChatSession, _error: Error) => {});
      const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
        hooks: {onError},
      });
      const caught = await orchestrator.processMessage(session).then(
        () => ({rejected: false, reason: null}),
        (error: unknown) => ({rejected: true, reason: error})
      );
      expect(caught).toEqual({rejected: true, reason});
      expect(onError).toHaveBeenCalledTimes(1);
      const reported = onError.mock.calls[0][1];
      expect(reported).toBeInstanceOf(Error);
      if (reason === existingError) expect(reported).toBe(reason);
      else expect(reported.cause).toBe(reason);
    }
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/onErrorCause.test.ts"

